{
  "title": "A Sunday in the City's Heart",
  "summary": "A relaxed day around the historic centre and Chapultepec, with no long rides and plenty of time to soak it all in.",
  "stops": [
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "We start with the Templo Mayor ruins, a deep dive into the city's Aztec roots before the crowds gather."
    },
    {
      "poi_id": "p3",
      "kind": "activity",
      "must_do_id": null,
      "note": "A short stroll to the Zócalo, the grand plaza where the city's history and daily life meet."
    },
    {
      "poi_id": "p20",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch at Al-Andalus, right in the same area, with hearty halal and vegetarian options to keep everyone happy."
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": null,
      "note": "A gentle afternoon in Bosque de Chapultepec, a green escape that's just a short ride from the centre."
    },
    {
      "poi_id": "p15",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner at Por Siempre Vegana Taquería, a relaxed vegan spot beside the park to end the day without rushing."
    }
  ]
}

{
  "title": "A Sunday Close to Home",
